const grimm = context.rulePiece;
if (!grimm || grimm.currentHp <= 0) return { success: false };
if (!context.sourcePiece || context.sourcePiece.instanceId !== grimm.instanceId) return { success: false };
if (!(context.damage > 0) || context.skillId === 'grimmjow-destruction-instinct') return { success: false };
context.damageQueue.push({
  attacker: grimm,
  target: grimm,
  damage: 1,
  damageType: 'true',
  skillId: 'grimmjow-destruction-instinct'
});
return { success: true };
